package com.nexushr.service; import com.nexushr.dto.RequestDtos.*; import com.nexushr.entity.*; import com.nexushr.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class LeaveService { final LeaveRequestRepository repo; final EmployeeService emp; public LeaveService(LeaveRequestRepository r,EmployeeService e){repo=r;emp=e;} public List<LeaveRequest> mine(String email){return repo.findByEmployeeIdOrderByCreatedAtDesc(emp.current(email).getId());} public List<LeaveRequest> pending(){return repo.findByStatusOrderByCreatedAtDesc(LeaveStatus.PENDING);} public LeaveRequest create(String email,LeaveRequestDto x){if(x.endDate().isBefore(x.startDate()))throw new IllegalArgumentException("End date before start date");var l=new LeaveRequest();l.setEmployee(emp.current(email));l.setType(LeaveType.valueOf(x.type()));l.setStartDate(x.startDate());l.setEndDate(x.endDate());l.setReason(x.reason());return repo.save(l);} public LeaveRequest decide(UUID id,LeaveDecision x){var l=repo.findById(id).orElseThrow();l.setStatus(LeaveStatus.valueOf(x.status()));l.setReviewerComment(x.comment());return repo.save(l);}}
